using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.IO;
using System.Web.Script.Serialization;
using ShatteredSail.Core.Gameplay;
class Program {
static string outputRoot; static CoreVoyageSession s; static bool strict; static int persistentCrew; static List<object> rows=new List<object>(); static StreamWriter actions;
static void Need(bool ok,string why){if(!ok)throw new Exception(why);}
static int Ix(string id)=>Enumerable.Range(0,CoreVoyageSession.CardLibrary.Count).Single(i=>CoreVoyageSession.CardLibrary[i].Id==id);
static void SetDeck(NavalBattleStage st,string[] ids){Need(s.SetBattleDeck(st,ids.Select(Ix).ToArray()),"deck "+st+" / "+string.Join(",",ids));}
static void Setup(string seed){s=new CoreVoyageSession();s.RestoreTreasureProgress(new CoreTreasureProgress{pirateExperience=5400});Need(s.RestoreCardPackProgress(null,10),"owned cards");Need(s.SelectShip(7),"ship");s.SelectRoute(2);s.SetSeed(seed);s.ConfigureDepartureCrew(28,0);s.ConfigureCrewCapabilities(false,false,false,false,false,false);s.ConfigureSpecialCardSources(new string[0],new string[0]);s.ConfigureComponentBonuses(0,0,0,0,0);s.ConfigureBattleEquipment(1,1);s.RestoreProfile(10000000,s.CurrentPort);
var ship=new[]{"card_approach","card_approach","card_full_sail_turn","card_full_sail_turn","card_emergency_repair","card_emergency_repair","card_brace","card_brace","card_energy_order","card_energy_order"};
var board=new[]{"card_boarding_blood_06","card_boarding_blood_06","card_boarding_tide_06","card_boarding_tide_06","card_boarding_basic_09","card_boarding_basic_09","card_boarding_tide_02","card_boarding_tide_02","card_boarding_basic_06","card_boarding_basic_07"};
SetDeck(NavalBattleStage.Preparation,ship);SetDeck(NavalBattleStage.Naval,ship);SetDeck(NavalBattleStage.Boarding,board);foreach(var id in ship.Concat(board).Distinct()){int ix=Ix(id);while(s.GetCardUpgradeCost(ix)>0)Need(s.TryUpgradeBattleCard(ix,out string reason),reason);}
s.Cargo.Water=s.Cargo.Food=s.Cargo.Beer=s.Cargo.Iron=s.Cargo.Cloth=0;s.Cargo.Powder=20;s.Cargo.Cannonballs=20;s.Cargo.Wood=120;s.Cargo.Medicine=500;Need(s.Cargo.UsedVolume<=s.CargoCapacityValue,"cargo");if(seed.EndsWith("-0")){var defs=new List<string>();foreach(NavalBattleStage stage in Enum.GetValues(typeof(NavalBattleStage))){defs.Add(stage.ToString());foreach(var g in s.GetBattleDeck(stage).GroupBy(i=>i)){var c=s.GetBattleCard(g.Key);defs.Add(c.Id+" | "+c.Name+" | +"+s.GetCardUpgradeLevel(c.Id)+" | x"+g.Count());}}File.WriteAllLines(Path.Combine(outputRoot,"deck.txt"),defs); }s.StartVoyage();Need(s.Phase==CoreDemoPhase.Sailing,"start voyage "+s.Phase);persistentCrew=264;
}
static object State()=>new{hull=s.Hull,maxHull=s.MaxHull,crew=persistentCrew,powder=s.Cargo.Powder,balls=s.Cargo.Cannonballs,wood=s.Cargo.Wood,medicine=s.Cargo.Medicine,volume=s.Cargo.UsedVolume};
static double Score(int index){var c=s.GetBattleCard(index);var b=s.Battle;var e=s.GetBattleCardEffects(c,b.Stage);bool boarding=b.Stage==NavalBattleStage.Boarding,prep=b.Stage==NavalBattleStage.Preparation;if(strict&&(e.Repair>0||c.BoardingSpec?.Key=="blood_06"||c.BoardingSpec?.Key=="basic_07"))return 0;if(c.BoardingSpec?.Key=="curse_10")return 1000;if(c.Action==NavalBattleCardAction.Energize||c.BoardingSpec?.Key=="basic_09")return 100;
int enemy=boarding?b.EnemyBoardingHealth:b.EnemyHull,hp=boarding?b.PlayerBoardingHealth:s.Hull,max=boarding?b.PlayerMaxBoardingHealth:s.MaxHull;int attack=CoreBattleIntentPresentation.Build(s).Where(x=>x.IsAttack).Sum(x=>x.Amount??0);int repair=Math.Min(max-hp,e.Repair),block=Math.Min(Math.Max(0,(prep?14:attack)-b.PlayerBlock),e.Block+(c.Block>0&&!boarding?b.PlayerDeckBuff:0));double score=repair*(hp<max*.8?3:1)+block*(hp<=attack*2?2:1);if(boarding)score=repair*(hp<=attack*2?3.5:1.2)+block*(hp<=attack*2?3.5:2.1);int damage=e.Damage+(c.Action==NavalBattleCardAction.Cannon?Math.Max(0,(s.EffectiveFirepower-8)/2)+b.PlayerLoadedShot:0);if(boarding&&c.BoardingSpec?.Key=="blood_06")score+=Math.Min(max-hp,Math.Max(0,damage-b.EnemyBlock))*(hp<=attack*2?3.5:1.8);if(boarding&&c.BoardingSpec?.Key=="basic_07"&&s.Cargo.Medicine>0)score+=Math.Min(max-hp+attack*2,50)*(hp<max*.75?1.5:.8);if(damage>=enemy+b.EnemyBlock)return 10000/(s.GetBattleCardEnergyCost(index)+.65);if(boarding)score+=damage*1.7;else if(!prep)score+=damage*.5;if(c.Draw>0&&b.Hand.Count<7)score+=c.Draw*(b.Hand.Count<4?6:2);
switch(c.Action){case NavalBattleCardAction.Polish:if(b.PlayerDeckBuff<c.StrategyLimit)score+=prep?35:9;break;case NavalBattleCardAction.Approach:case NavalBattleCardAction.Circle:case NavalBattleCardAction.Turn:if(b.DistanceMeters>60)score+=40;break;case NavalBattleCardAction.Navigator:case NavalBattleCardAction.Parallel:if(b.DistanceMeters>60)score+=44;else if(b.Alignment!=NavalBattleAlignment.Parallel)score+=65;break;case NavalBattleCardAction.Retreat:return 0;}
return score/(s.GetBattleCardEnergyCost(index)+.65);}
static bool Move(){if(!s.NavalActionMovementActive||s.Battle.NavalActionPoints<=0)return false;var target=s.Battle.EnemyPositionMeters;int distance(VoyagePoint p)=>(int)Math.Round((Math.Abs(p.X-target.X)+Math.Abs(p.Y-target.Y))/100);if(distance(s.Battle.PlayerPositionMeters)<=1)return false;bool appended=false;int before=distance(s.Battle.PlayerPositionMeters);for(int i=0;i<5;i++){var steps=s.GetNavalLegalNextSteps().Where(p=>distance(p)>0).OrderBy(distance).ToArray();if(steps.Length==0||distance(steps[0])>=before)break;Need(s.TryAppendNavalMovementStep(steps[0],out string why),why);appended=true;before=distance(steps[0]);if(before<=1)break;}if(!appended)return false;Need(s.CommitNavalMovement(out string reason),reason);if(s.Battle!=null&&s.Battle.NavalAwaitingHeadingSelection){var p=s.Battle.PlayerPositionMeters;float angle=Math.Abs(target.X-p.X)>=Math.Abs(target.Y-p.Y)?(target.X>=p.X?0:180):(target.Y>=p.Y?90:270);float chosen=s.GetNavalArrivalHeadings().OrderBy(h=>Math.Abs(((h-angle+540)%360)-180)).First();Need(s.ConfirmNavalArrivalHeading(chosen,out reason),reason);}return true;}
static bool Fight(CoreEncounter enc,string seed){typeof(CoreVoyageSession).GetProperty("ActiveEncounter").SetValue(s,enc);typeof(CoreVoyageSession).GetMethod("StartBattleCore",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,new object[]{enc,true,null,persistentCrew,null});var b=s.Battle;int startCrew=persistentCrew;var before=State();b.PlayerBoardingHealth=persistentCrew;int turns=0,cards=0,hullHeal=0,crewHeal=0;bool entered=false;for(int a=0;a<1800&&s.Phase==CoreDemoPhase.Battle;a++){int oldHull=s.Hull,oldCrew=b.PlayerBoardingHealth;var oldStage=b.Stage;string act;
if(s.CanBoard(out _)){Need(s.TryBoard(),"board");act="board";}else if(s.CanRam(out _)){Need(s.TryRam(),"ram");act="ram";}else {int best=-1;double score=.01;for(int h=0;h<b.Hand.Count;h++){if(!s.CanPlayCard(h))continue;double p=Score(b.Hand[h]);if(p>score){score=p;best=h;}}if(best>=0){act=s.GetBattleCard(b.Hand[best]).Id;Need(s.PlayCard(best),act);cards++;}else if(Move()){act="move";}else{Need(s.EndBattleTurn(),"end");turns++;act="end";}}
if(oldStage!=NavalBattleStage.Boarding&&b.Stage==NavalBattleStage.Boarding){entered=true;}
if(strict){if(s.Hull>oldHull)typeof(CoreVoyageSession).GetProperty("Hull").SetValue(s,oldHull);if(oldStage==b.Stage&&b.PlayerBoardingHealth>oldCrew)b.PlayerBoardingHealth=oldCrew;}
hullHeal+=Math.Max(0,s.Hull-oldHull);if(oldStage==b.Stage)crewHeal+=Math.Max(0,b.PlayerBoardingHealth-oldCrew);actions.WriteLine(seed+","+enc.Id+","+a+","+b.Stage+","+act+","+s.Hull+","+b.PlayerBoardingHealth+","+b.EnemyBoardingHealth+","+s.Cargo.Wood+","+s.Cargo.Medicine);
if(entered&&b.PlayerBoardingHealth<=0)break;
}if(entered)persistentCrew=b.PlayerBoardingHealth;bool won=s.Phase==CoreDemoPhase.Sailing&&persistentCrew>0;rows.Add(new{seed,id=enc.Id,name=enc.Name,won,turns,cards,hullHeal,crewHeal,start=before,end=State(),enemyHull=b.EnemyHull,enemyCrew=b.EnemyBoardingHealth});Console.WriteLine(seed+" "+enc.Name+" "+won+" hull="+s.Hull+" crew="+persistentCrew+" W/M="+s.Cargo.Wood+"/"+s.Cargo.Medicine);return won;}
static void Main(string[] args){string output=args[0];outputRoot=output;strict=args.Length>1&&args[1]=="strict";Directory.CreateDirectory(output);actions=new StreamWriter(Path.Combine(output,"actions-"+(strict?"strict":"sustain")+".csv"));actions.WriteLine("seed,boss,actionIndex,stage,action,hull,crew,enemyCrew,wood,medicine");int runs=args.Length>2?int.Parse(args[2]):3;int won=0;var runSummary=new List<object>();for(int run=0;run<runs;run++){int passed=0;string seed="ENDURANCE-20261104-"+run;Setup(seed);foreach(var enc in CoreRouteBossCatalog.All.Select(x=>x.CreateEncounter()).Concat(new[]{CoreLegendaryWarships.CreateTreasureEncounter()}).Concat(CoreLegendaryWarships.All.Select(x=>x.CreateEncounter()))){if(!Fight(enc,seed))break;passed++;}if(passed==13)won++;runSummary.Add(new{seed,passed,end=State()});}actions.Dispose();File.WriteAllText(Path.Combine(output,"results-"+(strict?"strict":"sustain")+".json"),new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{strict,runs,won,runSummary,rows}));}
}
